/// <summary>
/// MPJ_24248 Price Data Extract
/// </summary>
[ExtensionOf(tableStr(EcoResProductCategory))]
Public final class METEcoResProductCategoryTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Table Update
    /// </summary>
    public void update()
    {
        boolean     fieldUpdated = false;

        if(this.Category != this.orig().Category)
        {
            fieldUpdated = true;
        }
        
        next update();

        if(fieldUpdated && GUPParameters::find().METPriceChangeTrackingEnable)
        {
            METPriceChangeEventProduct::metProcessTrackChange(InventTable::findByProduct(this.Product));
        }
    }
